import { muatProduk, renderProduk } from './katalog.js';
import { pasangPencarian } from './pencarian.js';
import { pasangKeranjang, siapkanRiwayatContoh } from './keranjang.js';
import { pasangVoucher } from './harga-promo.js';
import { pasangPromo } from './promo.js';
import { pasangGulir } from './gulir.js';
import { pasangKaki } from './kategori.js';

async function mulai() {
  pasangPromo();
  pasangGulir();

  const produk = await muatProduk();
  siapkanRiwayatContoh(produk);

  pasangPencarian();
  pasangKeranjang();
  pasangVoucher();
  pasangKaki(produk);
  renderProduk(produk);

  if (window.Lacak) window.Lacak.kirim('page_view', { halaman: 'flashsale-1212', jumlahProduk: produk.length });
}

mulai();

// Alat ukur untuk tugas: aktif jika URL diberi ?ukur=1
if (new URLSearchParams(location.search).has('ukur')) {
  import('/alat/ukur.js');
}

// Katalog: menyimpan data produk dan menggambar kisi kartu produk.

import { $, el, formatRupiah, formatRibuan, hargaSetelahDiskon } from './util.js';
import { tambahKeKeranjang, beliSekarang } from './keranjang.js';
import { periksaGulir } from './gulir.js';

export const keadaan = {
  semuaProduk: [],
  ditampilkan: [],
  hargaVoucher: new Map(), // id produk -> harga setelah voucher
};

export async function muatProduk() {
  const respons = await fetch('/api/produk');
  keadaan.semuaProduk = await respons.json();
  return keadaan.semuaProduk;
}

function buatKartu(produk) {
  const kartu = el('article', 'kartu');
  kartu.dataset.id = produk.id;

  if (produk.flashSale) kartu.append(el('span', 'lencana-kilat', '⚡ Kilat'));

  const media = el('a', 'kartu-media');
  media.href = '#produk-' + produk.id;
  const gambar = document.createElement('img');
  gambar.src = produk.gambar;
  gambar.alt = produk.nama;
  media.append(gambar);

  const badan = el('div', 'kartu-badan');
  badan.append(el('h3', 'kartu-judul', produk.nama));

  const harga = el('div', 'harga');
  harga.append(el('span', 'harga-kini', formatRupiah(hargaSetelahDiskon(produk))));
  if (produk.diskon > 0) {
    harga.append(el('span', 'harga-asli', formatRupiah(produk.harga)));
    harga.append(el('span', 'harga-diskon', '-' + produk.diskon + '%'));
  }
  const hargaVoucher = keadaan.hargaVoucher.get(produk.id);
  if (hargaVoucher) harga.append(el('span', 'harga-voucher', 'Pakai voucher: ' + formatRupiah(hargaVoucher)));
  badan.append(harga);

  badan.append(el('div', 'keterangan', '★ ' + produk.rating.toLocaleString('id-ID') + ' | ' + formatRibuan(produk.terjual) + ' terjual'));
  badan.append(el('div', 'keterangan', produk.kota));

  const aksi = el('div', 'aksi');
  const tombolTambah = el('button', 'tombol-tambah', '+ Keranjang');
  tombolTambah.type = 'button';
  tombolTambah.addEventListener('click', () => tambahKeKeranjang(produk, tombolTambah));
  const tombolBeli = el('button', 'tombol-beli', 'Beli sekarang');
  tombolBeli.type = 'button';
  tombolBeli.addEventListener('click', () => beliSekarang(produk, tombolBeli));
  aksi.append(tombolTambah, tombolBeli);
  badan.append(aksi);

  kartu.append(media, badan);
  return kartu;
}

// Judul produk panjangnya beda-beda (1-3 baris). Supaya harga & tombol dalam
// satu deret sejajar rapi, tinggi judul disamakan mengikuti judul tertinggi.
// Mengukur semua judul terlalu lambat, jadi cukup ukur sebagian sebagai contoh.
const JUMLAH_CONTOH = 24;

function samakanTinggiJudul() {
  const judul = document.querySelectorAll('.kartu-judul');
  let tertinggi = 0;
  for (let i = 0; i < judul.length && i < JUMLAH_CONTOH; i++) {
    const j = judul[i];
    j.style.height = 'auto';
    const tinggi = j.offsetHeight;
    if (tinggi > tertinggi) tertinggi = tinggi;
    j.style.height = tertinggi + 'px';
  }
  judul.forEach((j) => { j.style.height = tertinggi + 'px'; });
}

export function renderProduk(daftar) {
  const kisi = $('#kisi');
  keadaan.ditampilkan = daftar;
  kisi.innerHTML = '';

  if (daftar.length === 0) {
    const kosong = el('div', 'kosong');
    kosong.append(el('strong', '', 'Produk tidak ditemukan.'), el('p', '', 'Periksa ejaan, atau coba kata kunci yang lebih umum seperti "sepatu" atau "serum".'));
    kisi.append(kosong);
  }

  for (const produk of daftar) {
    kisi.append(buatKartu(produk));
  }

  samakanTinggiJudul();
  $('#ringkasan').textContent = daftar.length.toLocaleString('id-ID') + ' produk ditampilkan';
  periksaGulir();
}

export function perbaruiHargaVoucherDiKartu() {
  renderProduk(keadaan.ditampilkan);
}

// Pencarian, saringan kategori, dan pengurutan.

import { $, el, hargaSetelahDiskon } from './util.js';
import { keadaan, renderProduk } from './katalog.js';

const saringan = { kata: '', kategori: 'Semua', urut: 'relevan' };

// "Sepatu Lari" == "sepatu  lari" == "SEPATU-LARI"
function normalkan(teks) {
  return teks
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function cocok(produk, kunci) {
  const teks = normalkan(produk.nama + ' ' + produk.merek + ' ' + produk.kategori + ' ' + produk.kota);
  return kunci.split(' ').every((k) => teks.includes(k));
}

const PEMBANDING = {
  murah: (a, b) => hargaSetelahDiskon(a) - hargaSetelahDiskon(b),
  mahal: (a, b) => hargaSetelahDiskon(b) - hargaSetelahDiskon(a),
  laris: (a, b) => b.terjual - a.terjual,
  rating: (a, b) => b.rating - a.rating || b.terjual - a.terjual,
};

export function terapkanSaringan() {
  const kunci = normalkan(saringan.kata);
  let hasil = keadaan.semuaProduk.filter((p) => {
    if (saringan.kategori !== 'Semua' && p.kategori !== saringan.kategori) return false;
    if (kunci && !cocok(p, kunci)) return false;
    return true;
  });
  if (PEMBANDING[saringan.urut]) hasil = hasil.slice().sort(PEMBANDING[saringan.urut]);
  renderProduk(hasil);

  if (window.Lacak && kunci) window.Lacak.kirim('search', { kata: saringan.kata, jumlah: hasil.length });
}

export function pasangPencarian() {
  const kolom = $('#kolom-cari');
  kolom.addEventListener('input', () => {
    saringan.kata = kolom.value;
    terapkanSaringan();
  });

  $('#pilih-urut').addEventListener('change', (e) => {
    saringan.urut = e.target.value;
    terapkanSaringan();
  });

  const wadah = $('#keping-kategori');
  const kategori = ['Semua', ...new Set(keadaan.semuaProduk.map((p) => p.kategori))];
  for (const nama of kategori) {
    const keping = el('button', 'keping', nama);
    keping.type = 'button';
    keping.setAttribute('aria-pressed', String(nama === 'Semua'));
    keping.addEventListener('click', () => {
      saringan.kategori = nama;
      wadah.querySelectorAll('.keping').forEach((k) => k.setAttribute('aria-pressed', String(k === keping)));
      terapkanSaringan();
    });
    wadah.append(keping);
  }
}

// Keranjang belanja, riwayat penelusuran, dan "Beli sekarang".
// Semua disimpan di localStorage supaya tetap ada walau halaman dimuat ulang.

import { $, el, formatRupiah, hargaSetelahDiskon, salinDalam, tampilkanToast } from './util.js';

const KUNCI_KERANJANG = 'tk_keranjang';
const KUNCI_RIWAYAT = 'tk_riwayat';

const KONFIG = { maksPerProduk: 99, mataUang: 'IDR', sumber: 'web-flashsale-1212' };

function bacaKeranjang() {
  return JSON.parse(localStorage.getItem(KUNCI_KERANJANG) || '[]');
}
function simpanKeranjang(isi) {
  localStorage.setItem(KUNCI_KERANJANG, JSON.stringify(isi));
}
function bacaRiwayat() {
  return JSON.parse(localStorage.getItem(KUNCI_RIWAYAT) || '[]');
}
function simpanRiwayat(riwayat) {
  localStorage.setItem(KUNCI_RIWAYAT, JSON.stringify(riwayat));
}

// Riwayat aktivitas dipakai tim rekomendasi ("Karena kamu melihat...").
// Untuk pengembangan, kita isi dengan data contoh pelanggan lama yang aktif
// sejak 2023 supaya kondisinya mirip pengguna sungguhan.
export function siapkanRiwayatContoh(semuaProduk) {
  if (localStorage.getItem(KUNCI_RIWAYAT)) return;
  const riwayat = [];
  const jenis = ['lihat', 'lihat', 'lihat', 'cari', 'keranjang', 'beli'];
  let waktu = Date.parse('2023-01-05T08:00:00+07:00');
  for (let i = 0; i < 9000; i++) {
    const p = semuaProduk[(i * 131) % semuaProduk.length];
    waktu += 1000 * 60 * (7 + (i % 190));
    riwayat.push({ t: waktu, jenis: jenis[i % jenis.length], id: p.id, nama: p.nama, kategori: p.kategori, harga: p.harga });
  }
  simpanRiwayat(riwayat);
}

export function perbaruiLencana() {
  const total = bacaKeranjang().reduce((n, item) => n + item.jumlah, 0);
  $('#lencana-keranjang').textContent = total;
}

function gambarPanel() {
  const daftar = $('#daftar-keranjang');
  const isi = bacaKeranjang();
  daftar.innerHTML = '';
  let total = 0;
  if (isi.length === 0) daftar.append(el('li', '', 'Keranjang masih kosong. Tambahkan produk dari daftar.'));
  for (const item of isi) {
    total += item.harga * item.jumlah;
    const baris = el('li');
    baris.append(el('span', '', item.nama), el('span', 'jumlah', item.jumlah + ' x ' + formatRupiah(item.harga)));
    const hapus = el('button', 'hapus', 'Hapus dari keranjang');
    hapus.type = 'button';
    hapus.addEventListener('click', () => {
      simpanKeranjang(bacaKeranjang().filter((x) => x.id !== item.id));
      perbaruiLencana();
      gambarPanel();
    });
    baris.append(hapus);
    daftar.append(baris);
  }
  $('#total-keranjang').textContent = formatRupiah(total);
}

export function tambahKeKeranjang(produk, tombol) {
  const konfig = salinDalam(KONFIG);
  const keranjang = bacaKeranjang();
  const riwayat = bacaRiwayat();

  const ada = keranjang.find((item) => item.id === produk.id);
  if (ada) ada.jumlah = Math.min(ada.jumlah + 1, konfig.maksPerProduk);
  else keranjang.push({ id: produk.id, nama: produk.nama, harga: hargaSetelahDiskon(produk), jumlah: 1 });

  riwayat.push({ t: Date.now(), jenis: 'keranjang', id: produk.id, nama: produk.nama, kategori: produk.kategori, harga: produk.harga });

  // Tim data minta konteks selengkap mungkin di setiap event.
  window.Lacak.kirim('add_to_cart', { produk, keranjang, riwayat, sumber: konfig.sumber });

  simpanKeranjang(keranjang);
  simpanRiwayat(riwayat);

  // Data sudah aman tersimpan, baru tampilan diperbarui.
  perbaruiLencana();
  tombol.textContent = 'Ditambahkan ✓';
  tombol.classList.add('sudah');
  setTimeout(() => {
    tombol.textContent = '+ Keranjang';
    tombol.classList.remove('sudah');
  }, 1500);
  tampilkanToast('Ditambahkan ke keranjang: ' + produk.nama);
}

export async function beliSekarang(produk, tombol) {
  const konfig = salinDalam(KONFIG);
  const riwayat = bacaRiwayat();
  riwayat.push({ t: Date.now(), jenis: 'beli', id: produk.id, nama: produk.nama, kategori: produk.kategori, harga: produk.harga });
  window.Lacak.kirim('begin_checkout', { produk, riwayat, sumber: konfig.sumber });
  simpanRiwayat(riwayat);

  const respons = await fetch('/api/pesanan', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ produkId: produk.id, nama: produk.nama }),
  });
  const pesanan = await respons.json();

  tombol.textContent = 'Dipesan ✓';
  setTimeout(() => { tombol.textContent = 'Beli sekarang'; }, 1500);
  tampilkanToast('Pesanan ' + pesanan.id + ' dibuat: ' + produk.nama);
  perbaruiLencanaPesanan();
}

export async function perbaruiLencanaPesanan() {
  const respons = await fetch('/api/pesanan');
  const pesanan = await respons.json();
  $('#lencana-pesanan').textContent = pesanan.length;
  return pesanan;
}

export function pasangKeranjang() {
  const panel = $('#panel-keranjang');
  const tombolBuka = $('#tombol-keranjang');
  const buka = (ya) => {
    panel.hidden = !ya;
    tombolBuka.setAttribute('aria-expanded', String(ya));
    if (ya) gambarPanel();
  };
  tombolBuka.addEventListener('click', () => buka(panel.hidden));
  $('#tutup-keranjang').addEventListener('click', () => buka(false));
  $('#kosongkan-keranjang').addEventListener('click', () => {
    simpanKeranjang([]);
    perbaruiLencana();
    gambarPanel();
  });

  $('#tombol-pesanan').addEventListener('click', async () => {
    const pesanan = await perbaruiLencanaPesanan();
    if (pesanan.length === 0) return tampilkanToast('Belum ada pesanan. Tekan "Beli sekarang" pada produk untuk memesan.');
    const terakhir = pesanan.slice(-3).map((p) => p.id + ' (produk #' + p.produkId + ')').join(', ');
    tampilkanToast(pesanan.length + ' pesanan. Terakhir: ' + terakhir);
  });

  perbaruiLencana();
  perbaruiLencanaPesanan();
}

// Voucher: menghitung harga promo untuk setiap produk.
// Aturan promo bertingkat + simulasi cicilan ditentukan tim bisnis.

import { $, hargaSetelahDiskon, tampilkanToast } from './util.js';
import { keadaan, perbaruiHargaVoucherDiKartu } from './katalog.js';

const VOUCHER = {
  KILAT1212: { persen: 12, maksPotongan: 120000, minBelanja: 50000 },
  HEMAT50: { persen: 5, maksPotongan: 50000, minBelanja: 0 },
};

// Cicilan 0% sampai 24 bulan: cari tenor dengan angsuran paling ringan yang
// masih memenuhi batas minimal angsuran per bulan dari mitra pembiayaan.
function simulasiCicilan(harga) {
  let terbaik = { tenor: 1, angsuran: harga };
  for (let tenor = 1; tenor <= 24; tenor++) {
    let sisa = harga;
    let angsuran = Math.ceil(harga / tenor / 100) * 100;
    for (let bulan = 1; bulan <= tenor; bulan++) {
      const biayaAdmin = Math.round(sisa * 0.0005 * Math.log2(bulan + 1));
      sisa = sisa - angsuran + biayaAdmin;
      if (sisa < 0) sisa = 0;
    }
    angsuran += Math.ceil(sisa / tenor);
    if (angsuran >= 25000 && angsuran < terbaik.angsuran) terbaik = { tenor, angsuran };
  }
  return terbaik;
}

// Dibuat async supaya perhitungan tidak memblokir halaman.
async function hitungHargaPromo(produk, aturan) {
  const dasar = hargaSetelahDiskon(produk);
  if (dasar < aturan.minBelanja) return null;
  let potongan = Math.min(Math.round((dasar * aturan.persen) / 100), aturan.maksPotongan);
  if (produk.flashSale) potongan = Math.round(potongan / 2); // flash sale hanya dapat setengah
  let hargaAkhir = Math.max(dasar - potongan, 100);
  for (let i = 0; i < 40; i++) simulasiCicilan(hargaAkhir + i); // cek kestabilan pembulatan
  const cicilan = simulasiCicilan(hargaAkhir);
  return { hargaAkhir, cicilan };
}

async function terapkanVoucher(kode) {
  const aturan = VOUCHER[kode];
  if (!aturan) {
    tampilkanToast('Kode voucher "' + kode + '" tidak dikenal. Coba KILAT1212.');
    return;
  }

  const progres = $('#progres');
  const isi = $('#progres-isi');
  const teks = $('#progres-teks');
  progres.hidden = false;
  isi.style.width = '0%';

  const total = keadaan.semuaProduk.length;
  let selesai = 0;
  keadaan.hargaVoucher.clear();

  for (const produk of keadaan.semuaProduk) {
    // await di setiap produk supaya browser sempat menggambar progress bar
    const hasil = await hitungHargaPromo(produk, aturan);
    if (hasil) keadaan.hargaVoucher.set(produk.id, hasil.hargaAkhir);
    selesai++;
    const persen = Math.round((selesai / total) * 100);
    isi.style.width = persen + '%';
    teks.textContent = 'Menghitung harga promo… ' + persen + '% (' + selesai + ' dari ' + total + ' produk)';
  }

  perbaruiHargaVoucherDiKartu();
  progres.hidden = true;
  tampilkanToast('Voucher ' + kode + ' dipakai di ' + keadaan.hargaVoucher.size.toLocaleString('id-ID') + ' produk.');
  if (window.Lacak) window.Lacak.kirim('apply_voucher', { kode, jumlah: keadaan.hargaVoucher.size });
}

export function pasangVoucher() {
  const kolom = $('#kolom-voucher');
  $('#tombol-voucher').addEventListener('click', () => terapkanVoucher(kolom.value.trim().toUpperCase()));
  kolom.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') terapkanVoucher(kolom.value.trim().toUpperCase());
  });
}

// Perilaku saat halaman digulir: bayangan header, bar progres baca,
// tombol "Ke atas", efek kartu muncul, dan pencatatan impresi produk.

import { $ } from './util.js';

const sudahTercatat = new Set();

export function periksaGulir() {
  const kepala = $('#kepala');
  const bar = $('#bar-gulir');
  const keAtas = $('#ke-atas');

  const y = window.scrollY;
  kepala.classList.toggle('melayang', y > 8);
  keAtas.hidden = y < 900;

  const tinggiDokumen = document.documentElement.scrollHeight - window.innerHeight;
  bar.style.width = (tinggiDokumen > 0 ? (y / tinggiDokumen) * 100 : 0) + '%';

  // Kartu yang masuk layar dimunculkan dengan animasi, dan dicatat sebagai impresi.
  const tinggiLayar = window.innerHeight;
  const impresiBaru = [];
  document.querySelectorAll('.kartu').forEach((kartu) => {
    const kotak = kartu.getBoundingClientRect();
    const masukLayar = kotak.top < tinggiLayar + 80 && kotak.bottom > -80;
    if (masukLayar && !kartu.classList.contains('terlihat')) {
      kartu.classList.add('terlihat');
      kartu.style.minHeight = Math.round(kotak.height) + 'px'; // cegah kartu "mengempis" saat animasi
    }
    if (masukLayar && !sudahTercatat.has(kartu.dataset.id)) {
      sudahTercatat.add(kartu.dataset.id);
      impresiBaru.push(kartu.dataset.id);
    }
  });

  if (impresiBaru.length && window.Lacak) window.Lacak.kirim('impression', { produk: impresiBaru });
}

export function pasangGulir() {
  window.addEventListener('scroll', periksaGulir);
  window.addEventListener('resize', periksaGulir);

  // Cegah "pull to refresh" tak sengaja di Android ketika pengguna sedang di puncak halaman.
  let yAwal = 0;
  const utama = $('#utama');
  utama.addEventListener('touchstart', (e) => { yAwal = e.touches[0].clientY; }, { passive: false });
  utama.addEventListener('touchmove', (e) => {
    const menarikKeBawah = e.touches[0].clientY > yAwal;
    if (window.scrollY === 0 && menarikKeBawah) e.preventDefault();
    periksaGulir();
  }, { passive: false });
  utama.addEventListener('wheel', () => { periksaGulir(); }, { passive: false });

  $('#ke-atas').addEventListener('click', () => window.scrollTo({ top: 0 }));
}

// Elemen kampanye: hitung mundur, teks berjalan, dan banner promo.

import { $, el, tampilkanToast } from './util.js';

// Flash sale berakhir tengah malam nanti (waktu perangkat).
function akhirFlashSale() {
  const t = new Date();
  t.setHours(24, 0, 0, 0);
  return t.getTime();
}

const duaDigit = (n) => String(n).padStart(2, '0');

function pasangHitungMundur() {
  const akhir = akhirFlashSale();
  const awal = Date.now();
  const wadah = $('#hitung-mundur');
  const garis = $('#hm-garis');
  const jam = $('#hm-jam'), menit = $('#hm-menit'), detik = $('#hm-detik'), senti = $('#hm-senti');

  // 10 ms supaya angka perseratus detik terlihat mulus
  setInterval(() => {
    const sisa = Math.max(akhir - Date.now(), 0);
    jam.textContent = duaDigit(Math.floor(sisa / 3600000));
    menit.textContent = duaDigit(Math.floor((sisa % 3600000) / 60000));
    detik.textContent = duaDigit(Math.floor((sisa % 60000) / 1000));
    senti.textContent = duaDigit(Math.floor((sisa % 1000) / 10));

    // garis di bawah angka menyusut mengikuti sisa waktu
    const lebarPenuh = wadah.offsetWidth;
    garis.style.width = Math.round(lebarPenuh * (sisa / (akhir - awal + 1))) + 'px';
  }, 10);
}

function pasangTeksBerjalan() {
  const teks = $('#berjalan-teks');
  let x = teks.parentElement.offsetWidth;
  setInterval(() => {
    x -= 1;
    if (x < -teks.offsetWidth) x = teks.parentElement.offsetWidth;
    teks.style.left = x + 'px';
  }, 10);
}

async function pasangBannerPromo() {
  const respons = await fetch('/api/promo');
  const promo = await respons.json();

  const banner = el('section', 'promo-banner');
  const teks = el('div');
  teks.append(el('h2', '', promo.judul), el('p', '', promo.isi));
  const tombol = el('button', '', promo.tombol);
  tombol.type = 'button';
  tombol.addEventListener('click', () => {
    tampilkanToast('Syarat promo: berlaku 12 Desember, satu voucher per akun, tidak bisa digabung.');
    if (window.Lacak) window.Lacak.kirim('promo_click', { judul: promo.judul });
  });
  banner.append(teks, tombol);

  $('#utama').prepend(banner);
}

export function pasangPromo() {
  pasangHitungMundur();
  pasangTeksBerjalan();
  pasangBannerPromo();
}

// Bagian kaki halaman: merek paling laris & kategori yang sering dibeli bersamaan.

import { $, el, urutkanGelembung } from './util.js';

export function pasangKaki(semuaProduk) {
  // --- merek paling laris ---
  const terjualPerMerek = {};
  for (const p of semuaProduk) terjualPerMerek[p.merek] = (terjualPerMerek[p.merek] || 0) + p.terjual;
  const merek = Object.keys(terjualPerMerek).map((nama) => ({ nama, terjual: terjualPerMerek[nama] }));
  const teratas = urutkanGelembung(merek, (a, b) => b.terjual - a.terjual).slice(0, 5);
  const daftarMerek = $('#merek-populer');
  for (const m of teratas) daftarMerek.append(el('li', '', m.nama + ' (' + m.terjual.toLocaleString('id-ID') + ' terjual)'));

  // --- kategori terkait ---
  // TODO(rudi): ini O(n^2) dan ada querySelectorAll di dalam loop. HARUS dioptimasi sebelum 12.12!!!
  const kategori = [...new Set(semuaProduk.map((p) => p.kategori))];
  const daftarTerkait = $('#kategori-terkait');
  for (let i = 0; i < kategori.length; i++) {
    let pasangan = null;
    let skorTertinggi = -1;
    for (let j = 0; j < kategori.length; j++) {
      if (i === j) continue;
      const sudahAda = document.querySelectorAll('#kategori-terkait li').length;
      const skor = ((kategori[i].length * 31 + kategori[j].length * 17 + sudahAda) % 97);
      if (skor > skorTertinggi) { skorTertinggi = skor; pasangan = kategori[j]; }
    }
    daftarTerkait.append(el('li', '', kategori[i] + ' + ' + pasangan));
  }
}

// Fungsi bantu yang dipakai di banyak tempat.

export const $ = (selektor, akar = document) => akar.querySelector(selektor);

export function el(tag, kelas, teks) {
  const node = document.createElement(tag);
  if (kelas) node.className = kelas;
  if (teks !== undefined) node.textContent = teks;
  return node;
}

export function formatRupiah(angka) {
  const pemformat = new Intl.NumberFormat('id-ID', {
    style: 'currency',
    currency: 'IDR',
    maximumFractionDigits: 0,
  });
  return pemformat.format(angka);
}

export function formatRibuan(angka) {
  if (angka >= 1000) return (Math.floor(angka / 100) / 10).toLocaleString('id-ID') + ' rb';
  return String(angka);
}

export function hargaSetelahDiskon(produk) {
  return Math.round((produk.harga * (100 - produk.diskon)) / 100 / 100) * 100;
}

// Salinan dalam (deep copy) supaya objek konfigurasi tidak termutasi.
export function salinDalam(objek) {
  return JSON.parse(JSON.stringify(objek));
}

// Pengurutan sederhana, dipakai untuk daftar pendek di bagian kaki halaman.
export function urutkanGelembung(daftar, banding) {
  const hasil = daftar.slice();
  for (let i = 0; i < hasil.length; i++) {
    for (let j = 0; j < hasil.length - i - 1; j++) {
      if (banding(hasil[j], hasil[j + 1]) > 0) {
        const tmp = hasil[j];
        hasil[j] = hasil[j + 1];
        hasil[j + 1] = tmp;
      }
    }
  }
  return hasil;
}

let pengaturWaktuToast;
export function tampilkanToast(pesan) {
  const toast = $('#toast');
  toast.textContent = pesan;
  toast.classList.add('tampil');
  clearTimeout(pengaturWaktuToast);
  pengaturWaktuToast = setTimeout(() => toast.classList.remove('tampil'), 2600);
}

/**
 * ALAT UKUR (bukan bagian dari aplikasi; tidak perlu "diperbaiki").
 * Aktif dengan membuka http://localhost:3000/?ukur=1
 *
 * Menampilkan ringkasan: long task, perkiraan INP, CLS, dan frame lambat.
 * Angka di sini untuk memantau cepat. BUKTI diagnosis tetap harus dari
 * panel Performance di DevTools (flame chart), bukan dari panel ini.
 */
(() => {
  const data = {
    longTask: [],            // durasi (ms)
    interaksi: new Map(),    // interactionId -> { durasi, jenis, target }
    cls: 0, clsSesi: 0, clsTerakhir: 0, clsAwalSesi: 0,
    frameLambat: 0, frameTerburuk: 0,
  };

  const dukung = (jenis) => (PerformanceObserver.supportedEntryTypes || []).includes(jenis);

  if (dukung('longtask')) {
    new PerformanceObserver((l) => l.getEntries().forEach((e) => data.longTask.push(Math.round(e.duration))))
      .observe({ type: 'longtask', buffered: true });
  }

  if (dukung('event')) {
    new PerformanceObserver((l) => {
      for (const e of l.getEntries()) {
        if (!e.interactionId) continue;
        const lama = data.interaksi.get(e.interactionId);
        if (!lama || e.duration > lama.durasi) {
          const t = e.target;
          data.interaksi.set(e.interactionId, {
            durasi: Math.round(e.duration),
            jenis: e.name,
            target: t ? (t.id ? '#' + t.id : t.className ? '.' + String(t.className).split(' ')[0] : t.tagName.toLowerCase()) : '?',
            tundaInput: Math.round(e.processingStart - e.startTime),
            proses: Math.round(e.processingEnd - e.processingStart),
            presentasi: Math.round(e.startTime + e.duration - e.processingEnd),
          });
        }
      }
    }).observe({ type: 'event', durationThreshold: 16, buffered: true });
  }

  if (dukung('layout-shift')) {
    new PerformanceObserver((l) => {
      for (const e of l.getEntries()) {
        if (e.hadRecentInput) continue;
        // jendela sesi: jeda < 1 dtk, panjang maks 5 dtk (definisi CLS)
        if (e.startTime - data.clsTerakhir < 1000 && e.startTime - data.clsAwalSesi < 5000) data.clsSesi += e.value;
        else { data.clsSesi = e.value; data.clsAwalSesi = e.startTime; }
        data.clsTerakhir = e.startTime;
        if (data.clsSesi > data.cls) data.cls = data.clsSesi;
      }
    }).observe({ type: 'layout-shift', buffered: true });
  }

  let tSebelum = performance.now();
  const pantauFrame = (t) => {
    const selisih = t - tSebelum;
    tSebelum = t;
    if (selisih > 50) { data.frameLambat++; if (selisih > data.frameTerburuk) data.frameTerburuk = Math.round(selisih); }
    requestAnimationFrame(pantauFrame);
  };
  requestAnimationFrame(pantauFrame);

  function ringkas() {
    const durasi = [...data.interaksi.values()].sort((a, b) => b.durasi - a.durasi);
    // INP ~ interaksi terburuk (abaikan 1 terburuk per 50 interaksi)
    const inp = durasi.length ? durasi[Math.min(Math.floor(durasi.length / 50), durasi.length - 1)] : null;
    return {
      waktu: new Date().toISOString(),
      jumlahLongTask: data.longTask.length,
      longTaskTerlama: data.longTask.length ? Math.max(...data.longTask) : 0,
      totalBlokir: data.longTask.reduce((n, d) => n + Math.max(d - 50, 0), 0),
      jumlahInteraksi: durasi.length,
      inp: inp ? inp.durasi : null,
      inpRinci: inp,
      limaInteraksiTerlambat: durasi.slice(0, 5),
      cls: Math.round(data.cls * 1000) / 1000,
      frameLambat: data.frameLambat,
      frameTerburuk: data.frameTerburuk,
    };
  }

  // ---------- tampilan ----------
  const panel = document.createElement('div');
  panel.id = 'alat-ukur';
  panel.style.cssText = 'position:fixed;left:10px;bottom:10px;z-index:9999;width:268px;max-width:calc(100vw - 20px);padding:10px 12px;border-radius:10px;background:rgba(20,18,43,.94);color:#fff;font:12px/1.5 ui-monospace,Menlo,Consolas,monospace;contain:layout paint;';
  panel.innerHTML = '<div id="au-isi"></div><div style="display:flex;gap:6px;margin-top:8px"><button id="au-salin" type="button">Salin JSON</button><button id="au-reset" type="button">Reset</button><button id="au-kecil" type="button">Kecilkan</button></div>';
  let kecil = window.innerWidth < 600; // di layar sempit mulai dalam keadaan kecil
  document.body.append(panel);
  panel.querySelectorAll('button').forEach((b) => { b.style.cssText = 'flex:1;border:0;border-radius:6px;padding:5px;background:#ffd400;color:#14122b;font:inherit;font-weight:700;cursor:pointer'; });

  const warna = (nilai, baik, buruk) => (nilai == null ? '#aaa' : nilai <= baik ? '#5ee0a0' : nilai <= buruk ? '#ffd400' : '#ff6b81');
  const isi = panel.querySelector('#au-isi');
  function gambar() {
    const r = ringkas();
    panel.querySelector('#au-salin').style.display = panel.querySelector('#au-reset').style.display = kecil ? 'none' : '';
    panel.querySelector('#au-kecil').textContent = kecil ? 'Buka alat ukur' : 'Kecilkan';
    if (kecil) {
      isi.innerHTML = `INP <span style="color:${warna(r.inp, 200, 500)}">${r.inp ?? '-'}</span> | CLS <span style="color:${warna(r.cls, 0.1, 0.25)}">${r.cls}</span> | LT <span style="color:${warna(r.longTaskTerlama, 100, 300)}">${r.longTaskTerlama}</span>`;
      return;
    }
    isi.innerHTML =
      `<b>Alat ukur TokoKilat</b><br>` +
      `INP&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: <span style="color:${warna(r.inp, 200, 500)}">${r.inp ?? '-'} ms</span> (${r.jumlahInteraksi} interaksi)<br>` +
      `CLS&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: <span style="color:${warna(r.cls, 0.1, 0.25)}">${r.cls}</span><br>` +
      `Long task : ${r.jumlahLongTask}x, terlama <span style="color:${warna(r.longTaskTerlama, 100, 300)}">${r.longTaskTerlama} ms</span><br>` +
      `Blokir&nbsp;&nbsp;&nbsp;&nbsp;: ${r.totalBlokir} ms total<br>` +
      `Frame &gt;50ms: ${r.frameLambat}x, terburuk ${r.frameTerburuk} ms`;
  }
  setInterval(gambar, 1000);
  gambar();

  panel.querySelector('#au-salin').addEventListener('click', async () => {
    const teks = JSON.stringify(ringkas(), null, 2);
    try { await navigator.clipboard.writeText(teks); } catch { /* abaikan */ }
    console.log('[alat ukur]\n' + teks);
  });
  panel.querySelector('#au-kecil').addEventListener('click', () => { kecil = !kecil; gambar(); });
  panel.querySelector('#au-reset').addEventListener('click', () => {
    data.longTask.length = 0; data.interaksi.clear();
    data.cls = data.clsSesi = 0; data.frameLambat = data.frameTerburuk = 0;
    gambar();
  });

  window.AlatUkur = { ringkas };
})();

