body {
  background-color: rgb(0 0 0 / 31%);
}

.controls-line {
  display: flex;
  justify-content: center;
  margin: 10px 0;
}

.message-box {
  padding: 2px 4px;
  display: flex;
  align-items: center;
  cursor: default;
  overflow: hidden;
}

#paused-in-debugger {
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
}

.controls-line > * {
  background-color: rgb(255 255 194);
  border: 1px solid rgb(202 202 202);
  height: 22px;
  box-sizing: border-box;
}

.controls-line .button {
  width: 26px;
  margin-left: -1px;
  margin-right: 0;
  padding: 0;
  flex-shrink: 0;
  flex-grow: 0;
  cursor: pointer;
}

.controls-line .button .glyph {
  width: 100%;
  height: 100%;
  background-color: rgb(0 0 0 / 75%);
